function getChunks(text, limit = 800) {
    const paragraphs = text.split(/\n\n+/);
    let chunks = [];
    let current = "";

    for (let p of paragraphs) {
        if ((current.length + p.length) > limit) {
            if (current) chunks.push(current.trim());
            current = p;
        } else {
            current += "\n\n" + p;
        }
    }
    if (current) chunks.push(current.trim());
    return chunks;
}

